<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { crearAccion,listarAcciones,type Accion,type Option } from '../services/acciones'
const rows=ref<Accion[]>([]),secciones=ref<Option[]>([]),detail=ref<Accion|null>(null),modal=ref(false),criterio=ref(''),seccion=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref('')
const form=reactive({seccion_id:'',nombre:'',descripcion:'',duracion:'',proceso:'',se_informa:'',movimiento_genera:''})
async function load(p=1){page.value=p;loading.value=true;error.value='';try{const r=await listarAcciones(criterio.value,seccion.value,p);rows.value=r.data;secciones.value=r.secciones;total.value=r.total;lastPage.value=r.last_page}catch(e){error.value=msg(e)}finally{loading.value=false}}
function open(){Object.assign(form,{seccion_id:'',nombre:'',descripcion:'',duracion:'',proceso:'',se_informa:'',movimiento_genera:''});modal.value=true}
async function submit(){if(form.nombre.trim().length<5||form.descripcion.trim().length<10){error.value='El nombre requiere 5 caracteres y la descripción 10 como mínimo.';return}saving.value=true;error.value='';try{await crearAccion(form);success.value='Acción registrada correctamente.';modal.value=false;await load(1)}catch(e){error.value=msg(e)}finally{saving.value=false}}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Comercialización / Acciones</nav><header class="hero"><div class="mark">AC</div><div><small>EVAN · CONFIGURACIÓN COMERCIAL</small><h1>Acciones del flujo</h1><p>Actividades disponibles para construir los procedimientos de atención.</p></div><strong>{{total}} acciones</strong><button @click="open">+ Agregar acción</button></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><section class="filters"><label>Buscar<input v-model.trim="criterio" placeholder="Nombre, proceso o descripción" @keyup.enter="load(1)"></label><label>Sección<select v-model="seccion"><option value="">Todas</option><option v-for="x in secciones" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><button @click="load(1)">Consultar</button></section><div v-if="loading" class="empty">Cargando acciones…</div><div v-else-if="!rows.length" class="empty">No se encontraron acciones.</div><section v-else class="cards"><article v-for="x in rows" :key="x.id"><header><span>{{x.seccion}}</span><small>#{{x.id}}</small></header><h2>{{x.nombre}}</h2><p>{{x.descripcion}}</p><dl><div><dt>Duración</dt><dd>{{x.duracion}}</dd></div><div><dt>Proceso</dt><dd>{{x.proceso}}</dd></div><div><dt>Se informa</dt><dd>{{x.se_informa}}</dd></div><div><dt>Flujos asociados</dt><dd>{{x.flujos||0}}</dd></div></dl><button @click="detail=x">Ver detalle</button></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal detail"><header><div><small>DETALLE DE ACCIÓN</small><h2>{{detail.nombre}}</h2><p>{{detail.seccion}}</p></div><button @click="detail=null">×</button></header><p class="description">{{detail.descripcion}}</p><dl><div><dt>Duración</dt><dd>{{detail.duracion}}</dd></div><div><dt>Proceso</dt><dd>{{detail.proceso}}</dd></div><div><dt>Se informa</dt><dd>{{detail.se_informa}}</dd></div><div><dt>Movimiento que genera</dt><dd>{{detail.movimiento_genera}}</dd></div></dl><footer><button class="clear" @click="detail=null">Cerrar</button></footer></section></div>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="submit"><header><div><small>CONFIGURACIÓN COMERCIAL</small><h2>Registrar acción</h2><p>La acción podrá incorporarse luego a uno o más flujos.</p></div><button type="button" @click="modal=false">×</button></header><label>Sección responsable *<select v-model="form.seccion_id" required><option value="">Seleccione</option><option v-for="x in secciones" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Nombre *<input v-model.trim="form.nombre" minlength="5" maxlength="255" required></label><label>Descripción *<textarea v-model.trim="form.descripcion" minlength="10" rows="4" required></textarea></label><div class="grid"><label>Duración *<input v-model.trim="form.duracion" maxlength="100" required></label><label>Proceso *<input v-model.trim="form.proceso" maxlength="100" required></label><label>Se informa *<input v-model.trim="form.se_informa" maxlength="100" required></label><label>Movimiento que genera *<input v-model.trim="form.movimiento_genera" maxlength="100" required></label></div><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Registrar'}}</button></footer></form></div></div></template>
<style scoped>
.page{--a:#7358b6;color:#34444d}nav{margin-bottom:16px;color:#96a1a7;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:700}.hero small,.modal small{color:var(--a);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.3rem}.hero p,.modal header p{margin:0;color:#7d898f;font-size:.65rem}.hero strong{margin-left:auto;font-size:.58rem}.hero button,.filters button,.pages button,.modal footer button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.56rem}.flash{padding:10px;font-size:.63rem}.good{color:#287258;background:#edf9f3}.error{color:#a13f43;background:#fff0f0}.filters{margin-top:13px;padding:12px;display:flex;align-items:end;gap:8px;background:#fff}.filters label{flex:1;font-size:.52rem}.filters label:first-child{flex:2}input,select,textarea{width:100%;padding:9px;border:1px solid #d8e0e4;border-radius:6px;font:inherit;font-size:.58rem}.cards{margin-top:12px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.cards article{display:flex;flex-direction:column;padding:15px;border-top:3px solid var(--a);border-radius:9px;background:#fff}.cards header{display:flex;justify-content:space-between}.cards header span{padding:4px 7px;border-radius:9px;color:var(--a);background:#f1edfa;font-size:.48rem}.cards h2{font-size:.65rem}.cards>article>p{min-height:40px;color:#748087;font-size:.52rem}.cards dl,.detail dl{display:grid;grid-template-columns:1fr 1fr;gap:7px}.cards dt,.detail dt{color:#89949a;font-size:.46rem}.cards dd,.detail dd{margin:2px 0;font-size:.5rem;font-weight:700}.cards article>button{margin-top:auto;padding:8px;border:0;border-radius:5px;color:#fff;background:var(--a);font-size:.52rem}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff;font-size:.6rem}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,740px);max-height:92vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin:11px 0;font-size:.55rem}.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.modal footer{margin-top:15px;display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}.description{padding:12px;border-left:3px solid var(--a);background:#f6f4fb;font-size:.57rem}.detail dl div{padding:10px;background:#f7f8f9}@media(max-width:800px){.cards{grid-template-columns:1fr 1fr}.filters{align-items:stretch;flex-direction:column}.hero{flex-wrap:wrap}.hero strong{margin-left:0}}@media(max-width:520px){.cards,.grid{grid-template-columns:1fr}}
</style>
